using System.Diagnostics;using System.IO;using System.Windows;using System.Windows.Media;using T6AssetTool.Core;using Forms=System.Windows.Forms;using OpenFileDialog=Microsoft.Win32.OpenFileDialog;using MessageBox=System.Windows.MessageBox;using Brushes=System.Windows.Media.Brushes;using Color=System.Windows.Media.Color;
namespace T6AssetTool.Gui;
public partial class MainWindow:Window
{
 public MainWindow(){InitializeComponent();IPak.Text=@"C:\Users\thrif\Downloads\zm_transit_tm.ipak";Output.Text=@"C:\GAMES\BO2AssetDecompiler\Transit IPAK DDS";Zones.Visibility=Visibility.Collapsed;AddZone.Visibility=Visibility.Collapsed;RemoveZone.Visibility=Visibility.Collapsed;PickIPak.Click+=(_,_)=>PickPackage();PickOutput.Click+=(_,_)=>PickDestination();OpenOutput.Click+=(_,_)=>{if(Directory.Exists(Output.Text))Process.Start(new ProcessStartInfo("explorer.exe",Output.Text){UseShellExecute=true});};Execute.Click+=async(_,_)=>await Run();}
 void PickPackage(){var d=new OpenFileDialog{Filter="Black Ops II Xbox IPAK|*.ipak"};if(d.ShowDialog()==true)IPak.Text=d.FileName;}void PickDestination(){using var d=new Forms.FolderBrowserDialog{Description="Select clean DDS output directory",SelectedPath=Output.Text};if(d.ShowDialog()==Forms.DialogResult.OK)Output.Text=d.SelectedPath;}
 async Task Run(){string ipakPath=IPak.Text,outputPath=Output.Text;if(!File.Exists(ipakPath)){MessageBox.Show("Select a valid Xbox 360 BO2 IPAK.","Input required");return;}Execute.IsEnabled=false;Progress.IsIndeterminate=true;Status.Text="PROCESSING";Status.Foreground=Brushes.Orange;StatusDot.Fill=Brushes.Orange;Summary.Text="IPAK EXTRACTION ACTIVE";Log.Clear();try{var progress=new Progress<string>(s=>{Log.AppendText($"{DateTime.Now:HH:mm:ss}  {s}\r\n");Log.ScrollToEnd();});var r=await Task.Run(()=>AssetExtractor.RunIPak(ipakPath,outputPath,s=>((IProgress<string>)progress).Report(s)));Status.Text="COMPLETE";Status.Foreground=new SolidColorBrush(Color.FromRgb(71,213,201));StatusDot.Fill=Status.Foreground;Summary.Text=$"{r.Textures} DDS TEXTURES";}catch(Exception e){Status.Text="FAILED";Status.Foreground=Brushes.IndianRed;StatusDot.Fill=Brushes.IndianRed;Summary.Text="JOB FAILED";Log.AppendText("ERROR  "+e+"\r\n");}finally{Progress.IsIndeterminate=false;Execute.IsEnabled=true;}}
}
